// Report table sorting in the report runtime (FEA-RP-22, TYP-37, FEA-CH-37). Tables from CSV
// files are generated by the release CLI and sorted by their header buttons at desktop and phone
// widths. Numbers sort by the value each cell shows, so integers past 2^53 and decimals that show
// the same value tie and keep the author's order in both directions, and ones that show different
// values order numerically. Empty cells stay last, text follows numbers, the cycle returns to the
// author's order and state, focus stays on the header and an open overflow stays open with the
// first rows in view. Quoted inline numbers sort as text, and formatted numbers (percent) by the
// value they show. CSV typing and readout precision are checked in core and the engine
// (csv_decimal_source.rs, numbers.rs).
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { cli, harness, root, serveStatic, watchErrors } from './browser-harness.mjs';

const h = await harness('csv-decimals');
const folder = join(h.dir, 'decimals');
mkdirSync(join(folder, 'data'), { recursive: true });
writeFileSync(join(folder, 'data/big.csv'), 'id,value\nmiddle,9007199254740993\nlow,9007199254740992\nhigh,9007199254740994\nless,8007199254740993\n');
writeFileSync(join(folder, 'data/ties.csv'), 'id,value\nwhole,1\nfraction,1.0\nabove,1.000000000000000000001\nbelow,0.999999999999999999999\nalias,10e-1\nhalf,0.5\n');
writeFileSync(join(folder, 'data/mixed.csv'), 'id,value\nb,beta\nempty-1,\nfive,5\na,alpha\nminus,-2\nempty-2,\n');
const table = (file, extra = '') => '\n```table\ndata: {csv: data/' + file + '}\ncolumns: [{key: id}, {key: value}]\n' + extra + '```\n';
// Quoted inline numbers are text (TYP-37); formatted numbers sort by the value they show.
const inline = (rows, extra = '') => '\n```table\ndata: {inline: ' + JSON.stringify(rows) + '}\ncolumns: [{key: id}, {key: value' + extra + '}]\n```\n';
writeFileSync(join(folder, 'report.rmd'), '---\ntitle: Decimals\nversion: "1"\n---\n\nSortable tables.\n'
  + table('big.csv') + table('ties.csv') + table('mixed.csv', 'max_rows: 3\n')
  + inline([{ id: 'ten', value: '10' }, { id: 'two', value: '2' }, { id: 'nine', value: '9' }])
  + inline([{ id: 'most', value: 1.2 }, { id: 'least', value: 0.09 }, { id: 'middle', value: 0.45 }], ', format: percent'));
execFileSync(cli, ['generate', join(folder, 'report.rmd'), '--format', 'json'], { cwd: root, stdio: 'pipe' });
const server = await serveStatic({ '/decimals/': join(folder, 'Rendered') });

const errors = [];
const failures = [];
const cases = [];
const check = async (label, fn) => {
  try {
    await fn();
    cases.push(label);
  } catch (error) {
    failures.push(`${label}: ${error.message}`);
  }
};

for (const width of [1100, 390]) {
  const page = await h.browser.newPage({ viewport: { width, height: 900 } });
  watchErrors(page, errors, `${width}: `);
  await page.goto(`${server.base}/decimals/report.html`);
  await page.locator('html[data-rv-runtime="started"]').waitFor();
  const tables = page.locator('.rv-table');
  const ids = k => tables.nth(k).locator('tbody tr td:first-child').allTextContents();
  const sortBy = async k => {
    const button = tables.nth(k).locator(':scope > table thead [data-rv-sort="value"]');
    await button.click();
    assert.equal(await button.evaluate(b => document.activeElement === b), true, 'focus stays on the header');
    return button.evaluate(b => b.closest('th').getAttribute('aria-sort'));
  };

  // Three integers past 2^53 all show 9.01 quadrillion; the page carries no finer digit to tell
  // them apart (FEA-CH-37).
  await check(`${width}: integers past 2^53 sort by the value they show and the cycle returns to the author's order`, async () => {
    assert.deepEqual(await ids(0), ['middle', 'low', 'high', 'less']);
    assert.equal(await sortBy(0), 'ascending');
    assert.deepEqual(await ids(0), ['less', 'middle', 'low', 'high']);
    assert.equal(await sortBy(0), 'descending');
    assert.deepEqual(await ids(0), ['middle', 'low', 'high', 'less']);
    assert.equal(await sortBy(0), 'none');
    assert.deepEqual(await ids(0), ['middle', 'low', 'high', 'less']);
  });

  await check(`${width}: decimals that show the same value keep the author's order in both directions`, async () => {
    assert.equal(await sortBy(1), 'ascending');
    assert.deepEqual(await ids(1), ['half', 'whole', 'fraction', 'above', 'below', 'alias']);
    assert.equal(await sortBy(1), 'descending');
    assert.deepEqual(await ids(1), ['whole', 'fraction', 'above', 'below', 'alias', 'half']);
    await sortBy(1);
  });

  await check(`${width}: numbers, then text, then empty cells; the overflow stays open`, async () => {
    const overflow = tables.nth(2).locator('.rv-table__overflow');
    await overflow.locator('summary').click();
    assert.equal(await sortBy(2), 'ascending');
    assert.deepEqual(await ids(2), ['minus', 'five', 'a', 'b', 'empty-1', 'empty-2']);
    const main = await tables.nth(2).locator(':scope > table tbody td:first-child').allTextContents();
    assert.deepEqual(main, ['minus', 'five', 'a'], 'the first rows stay in view');
    assert.equal(await overflow.evaluate(d => d.open), true, 'the overflow stays open');
    assert.equal(await sortBy(2), 'descending');
    assert.deepEqual(await ids(2), ['b', 'a', 'five', 'minus', 'empty-1', 'empty-2']);
    assert.equal(await sortBy(2), 'none');
    assert.deepEqual(await ids(2), ['b', 'empty-1', 'five', 'a', 'minus', 'empty-2']);
  });

  await check(`${width}: quoted numbers sort as text and formatted numbers by their value`, async () => {
    assert.equal(await sortBy(3), 'ascending');
    assert.deepEqual(await ids(3), ['ten', 'two', 'nine']);
    await sortBy(3);
    await sortBy(3);
    assert.equal(await sortBy(4), 'ascending');
    assert.deepEqual(await ids(4), ['least', 'middle', 'most']);
    assert.equal(await sortBy(4), 'descending');
    assert.deepEqual(await ids(4), ['most', 'middle', 'least']);
    await sortBy(4);
  });
  await page.close();
}

await server.close();
h.save('csv-decimals.json', { cases, errors, failures });
await h.close();
if (errors.length) failures.push(...errors.map(e => `page error: ${e}`));
if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
console.log(`PASS ${cases.length} table sorting cases at desktop and phone widths`);
